# Lesson 3, part 1: index points, the multiplier, the trading screen, European and American.


def _B_ar(txt, d, c, n=0):
    """One labelled arrow of a flow diagram. d: 'r' points right, 'l' points left. c: colour class."""
    a = f'<div class="b-ar b-{d} {c}">{TX(txt)}</div>'
    return ST(n, a) if n else a


def _B_nd(name, sub='', me=False):
    s = f'<small>{TX(sub)}</small>' if sub else ''
    return f'<div class="b-nd{" b-me" if me else ""}"><b>{TX(name)}</b>{s}</div>'


# ---------------------------------------------------------------- index points
S('s-pts', 'נקודות של מדד', 'מדד, נקודה ומכפיל: שלוש הגדרות',
  '<div class="b-g3">'
  + DEF('מדד מניות (Stock index)', 'ממוצע <b>משוקלל</b> של מחירי קבוצת מניות שנבחרו לפי כללים קבועים. כל מניה מקבלת משקל, בדרך כלל לפי שווי השוק שלה: מחיר המניה כפול מספר המניות שבידי הציבור. המדד מוצג כמספר, ביחס לרמת בסיס שנקבעה ביום שבו התחיל.', 'מדד של שתי מניות: שווי השוק של א הוא 300 מיליון ש״ח, ושל ב 100 מיליון. המשקלות: 75% ו-25%. מניה א עולה ב-10% ו-ב לא זזה: המדד עולה ב-$75% × 10% = 7.5%$.', 1, cls='mini')
  + DEF('נקודת מדד (Index point)', 'יחידת המדידה של רמת המדד. שינוי של נקודה אחת הוא שינוי של 1 ברמת המדד. נקודה איננה סכום כסף: הערך הכספי שלה נקבע רק בחוזה, דרך המכפיל. נקודות הן שינוי מוחלט, ואחוזים הם שינוי יחסי.', 'מדד עלה מ-4,000 ל-4,040: עלייה של 40 נקודות, שהן $40 ÷ 4,000 = 1%$. אותן 40 נקודות במדד שעומד על 2,000 הן 2%.', 2, cls='mini')
  + DEF('מכפיל (Multiplier)', 'הסכום בשקלים שכל נקודת מדד שווה לפי החוזה. הבורסה קובעת אותו במפרט החוזה, והוא זהה לכל המשקיעים באותו חוזה. בחוזים על מדד ת״א 35, נקודה שווה 50 ש״ח.', 'מכפיל 50: עלייה של 40 נקודות שווה $40 × 50 = 2,000$ ש״ח בחוזה אחד, ו-4,000 ש״ח בשני חוזים.', 3, trm='mult', cls='mini')
  + '</div>'
  + ST(4, '<b class="ct">למה כאן חוזה עתידי (Futures), ולא חוזה אקדמה (Forward)?</b><div class="b-ff">'
       + '<div><b>' + TX('חוזה אקדמה (Forward)') + '</b><span>' + TX('הסכם פרטי בין שני צדדים. התנאים לפי בקשתם, והחשבון נעשה פעם אחת, ביום הפקיעה. אם הצד השני לא משלם, ההפסד שלכם.') + '</span></div>'
       + '<div><b>' + TX('חוזה עתידי (Futures)') + '</b><span>' + TX('אותו רעיון, אבל נסחר בבורסה. התנאים אחידים (גודל, מכפיל, מועד), מסלקה (Clearing house), גוף שערב לשני הצדדים, עומדת ביניהם, והרווח וההפסד נזקפים כל יום. נכיר אותה בחלק 2.') + '</span></div>'
       + '<div class="b-ffx">' + TX('חוזה על מדד נסחר בבורסה, ולכן הוא חוזה עתידי. החשבון ביום הפקיעה זהה לאקדמה: $(S_{T} − K) × מכפיל$. ההתחשבנות היומית מגיעה בחלק 3.') + '</div></div>', cls='card b-ffc'),
  kick=f'חלק {CUR[0]} · הגדרה והדגמה')


def _pn(n, lab, val, cls=''):
    return ST(n, f'<small>{TX(lab)}</small><b>{TX(val)}</b>', cls='pn ' + cls)


def _po(n, t):
    return ST(n, f'<span>{TX(t)}</span>', cls='po')


S('s-pts2', 'נקודות לשקלים: הרעיון', 'מנקודות לשקלים: הרעיון, בתרשים זרימה',
  '<div class="card qstem"><p>' + TX('קרן השקעות קונה (Long) חוזה עתידי אחד על מדד מניות שעומד היום על 4,000 נקודות, במחיר חוזה (K) של 4,000 נקודות. המכפיל 50 ש״ח לנקודה. <b>נדרש:</b> מה החשיפה בשקלים, ומה הרווח או ההפסד אם המדד יעלה ב-2% או יירד ב-5%?') + '</p></div>'
  + '<div class="b-lane"><b class="b-lt">' + TX('שאלה 1: כמה כסף החוזה מייצג?') + '</b><div class="b-row">'
  + _pn(1, 'רמת המדד היום', '4,000 נקודות') + _po(2, '×') + _pn(2, 'מכפיל', '50 ש״ח לנקודה') + _po(3, '=') + _pn(3, 'חשיפה (Exposure)', '200,000 ש״ח', 'res')
  + ST(3, TX('כאילו הקרן מחזיקה סל של מניות המדד בשווי 200,000 ש״ח.'), cls='b-why') + '</div></div>'
  + '<div class="b-lane"><b class="b-lt">' + TX('שאלה 2: כמה מרוויחים כשהמדד זז? (תרחיש: עלייה של 2%)') + '</b><div class="b-row">'
  + _pn(4, 'המדד בפקיעה ($S_{T}$)', '$4,000 × 1.02 = 4,080$') + _po(5, '−') + _pn(5, 'מחיר החוזה (K)', '4,000') + _po(6, '=') + _pn(6, 'שינוי בנקודות', '$+80$')
  + _po(7, '×') + _pn(7, 'מכפיל', '50') + _po(8, '=') + _pn(8, 'רווח בשקלים', '$+4,000$ ש״ח', 'res') + '</div></div>'
  + ST(9, TX('<b>ירידה של 5%:</b> המדד $4,000 × 0.95 = 3,800$, השינוי $3,800 − 4,000 = −200$ נקודות, וההפסד $−200 × 50 = −10,000$ ש״ח. בשקף הבא אתם בונים את זה באקסל.'), cls='band dg'),
  kick=f'חלק {CUR[0]} · תרשים זרימה')

