# ---------------------------------------------------------------- order types, on one order book
def _ob(n, hl):
    r = [('7', '60'), ('15', '61'), ('24', '62')]
    return ST(n, '<table class="ob"><tr><th>היצע (Ask)</th><th>כמות</th></tr>' + ''.join(f'<tr class="{"hit" if i < hl else ""}"><td>{p}</td><td>{q}</td></tr>' for i, (q, p) in enumerate(r)) + '</table>', cls='obw')


def _oc(n, name, he, rule, res, tail, cls):
    return ST(n, f'<b class="on" dir="ltr">{name}</b><small>{TX(he)}</small><p>{TX(rule)}</p><div class="or">{TX(res)}</div><p class="ot">{TX(tail)}</p>', cls='oc ' + cls)


